Here is the root cause:
The bug was caused by the reuse of a port that was in the FIN_WAIT_2 state due to the `close()` operation on a client socket. This led to a new client socket being assigned the same port, which resulted in SYN packets being sent to a CLOSE_WAIT socket from an unexpected CPU. This overwrote the receiver's `sk_incoming_cpu` with an incorrect CPU ID, causing the assertion failure in the test.

Here is the patch:
 #include <sched.h>

+#include <fcntl.h>
+
 #include <netinet/in.h>
 #include <sys/socket.h>
 #include "../kselftest_harness.h"

-#define CLIENT_PER_SERVER	32 /* More sockets, more reliable */
-#define NR_SERVER		self->nproc
-#define NR_CLIENT		(CLIENT_PER_SERVER * NR_SERVER)
-
 FIXTURE(so_incoming_cpu)
 {
-	int nproc;
 	int *servers;
 	union {
 		struct sockaddr addr;
 		struct sockaddr_in in_addr;
 	};
 	socklen_t addrlen;
 };


+static void write_sysctl(struct __test_metadata *_metadata,
+			 char *filename, char *string)
+{
+	int fd, len, ret;
+
